import type { Metadata } from "next";

export const YEAR = 2027;

// Stable localStorage key for this calendar's entries. Never reuse it for
// another year; each calendar year gets its own key.
export const STORAGE_KEY = "cbs-op-cal-2027-v2";

const TITLE = "2027 O&P Compliance Calendar | CBS Medical Billing & Consulting";
// The hero's lead sentence (approved copy).
const DESCRIPTION =
  "Compliance shouldn't be managed by memory. Use this calendar to track every deadline, put a name next to each one, and set 30- and 60-day reminders before January arrives.";

// Generated by app/opengraph-image.tsx. Listed explicitly because a route's
// own openGraph/twitter settings replace an inherited image.
const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Your 2027 O&P compliance calendar, a free O&P compliance resource from CBS Medical Billing & Consulting",
};

export const metadata: Metadata = {
  // Absolute title: the layout's title template doesn't apply to "/", which
  // sits in the root layout's own segment.
  title: { absolute: TITLE },
  description: DESCRIPTION,
  // "/" and "/2027" render the same page while 2027 is current; point search
  // engines at the permanent yearly URL.
  alternates: { canonical: "/2027" },
  // Share previews. Site name and X handle match cbsmedicalbilling.com.
  openGraph: {
    type: "website",
    locale: "en_US",
    url: "/2027",
    siteName: "CBS Medical Billing & Consulting",
    title: TITLE,
    description: DESCRIPTION,
    images: [SHARE_IMAGE],
  },
  twitter: {
    card: "summary_large_image",
    site: "@CBS_Billing",
    title: TITLE,
    description: DESCRIPTION,
    images: [SHARE_IMAGE],
  },
};
